CREATE TABLE IF NOT EXISTS adaptive_learning_snapshots(id VARCHAR(64) PRIMARY KEY,account_id VARCHAR(64) NOT NULL,mastery DOUBLE PRECISION NOT NULL CHECK(mastery BETWEEN 0 AND 100),readiness DOUBLE PRECISION NOT NULL CHECK(readiness BETWEEN 0 AND 100),consistency DOUBLE PRECISION NOT NULL CHECK(consistency BETWEEN 0 AND 100),risk VARCHAR(16) NOT NULL CHECK(risk IN('low','watch','high','critical')),evidence_count INTEGER NOT NULL CHECK(evidence_count>=0),model_version VARCHAR(32) NOT NULL,payload TEXT NOT NULL,generated_at TIMESTAMPTZ NOT NULL); CREATE INDEX IF NOT EXISTS ix_adaptive_account_time ON adaptive_learning_snapshots(account_id,generated_at DESC);
